def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    my_c = 0
    recent_opp_c = 0
    start = n - 10
    if start < 0:
        start = 0

    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
            if i >= start:
                recent_opp_c += 1
        if a == 'C':
            my_c += 1

    opp_d = n - opp_c

    if opp_c == 0:
        return 'D'

    safe = 0
    punished = 0
    for k in range(1, n - 1):
        if history[k][0] == 'D' and history[k][1] == 'C' and history[k - 1][1] == 'C':
            if history[k + 1][1] == 'C':
                safe += 1
            elif history[k + 1][1] == 'D':
                punished += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    if my_last == 'D' and opp_last == 'C' and safe == 0 and punished == 0:
        return 'C'

    exploitable = (punished == 0 and safe >= 1) or (safe >= 2 and safe > punished)

    if exploitable:
        if opp_last == 'C':
            return 'D'
        if opp_d_streak == 1 and recent_opp_c >= 6:
            return 'C'
        if recent_opp_c >= 8 and opp_c * 100 >= n * 70:
            return 'C'
        return 'D'

    if opp_last == 'D':
        if opp_d_streak >= 2:
            if recent_opp_c >= 8 and opp_c * 100 >= n * 80:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            if opp_c * 100 >= n * 50:
                return 'C'

        if recent_opp_c >= 7:
            return 'C'

        if opp_c * 100 >= n * 70 and rng.random() < 0.12:
            return 'C'

        if opp_c * 100 <= n * 40:
            return 'D'

        return 'D'

    if safe == 0 and punished == 0 and opp_d == 0 and n >= 6 and my_last == 'C':
        return 'D'

    if safe == 0 and punished == 0 and opp_d <= 1 and recent_opp_c >= 7 and n >= 8 and my_last == 'C':
        return 'D'

    if opp_c * 100 <= n * 40 and recent_opp_c < 7:
        return 'D'

    if safe + punished < 3 and opp_c * 100 >= n * 80 and n >= 20 and my_c * 100 >= n * 80:
        if rng.random() < 0.05:
            return 'D'

    if punished > 0 and safe == 0 and opp_c * 100 >= n * 88 and recent_opp_c >= 9 and n >= 25:
        if rng.random() < 0.06:
            return 'D'

    if n == 98:
        if recent_opp_c >= 6 or opp_c * 100 >= n * 75:
            return 'C'
        return 'D'

    if n >= 90 and opp_c * 100 >= n * 85 and recent_opp_c >= 8:
        if rng.random() < 0.1:
            return 'D'

    return 'C'
